SELECT *
FROM crm_sales_target

    deleted = '0'


            AND target_name LIKE CONCAT('%', #{query.targetName}, '%')


            AND target_no LIKE CONCAT('%', #{query.targetNo}, '%')


            AND dimension_type = #{query.dimensionType}


            AND period_type = #{query.periodType}


            AND target_year = #{query.targetYear}


            AND target_period = #{query.targetPeriod}


            AND status = #{query.status}


            AND owner_id = #{query.ownerId}


            AND dept_id = #{query.deptId}



ORDER BY update_time DESC
